function reducer(state, action) {
	switch (action.type) {
		case "focus": return {
			...state,
			isFocused: true
		};
		case "blur": return {
			...state,
			isFocused: false
		};
		case "openDialog": return {
			...initialState,
			isFileDialogActive: true
		};
		case "closeDialog": return {
			...state,
			isFileDialogActive: false
		};
		case "setDraggedFiles": return {
			...state,
			isDragActive: action.isDragActive,
			isDragAccept: action.isDragAccept,
			isDragReject: action.isDragReject,
			isDragUnknown: action.isDragUnknown,
			dragFileRejections: action.dragFileRejections
		};
		case "setProcessing": return {
			...state,
			isProcessing: action.isProcessing
		};
		case "setFiles": return {
			...state,
			acceptedFiles: action.acceptedFiles,
			fileRejections: action.fileRejections,
			dragFileRejections: [],
			isProcessing: false,
			isDragReject: false,
			isDragUnknown: false
		};
		case "setDragGlobal": return {
			...state,
			isDragGlobal: action.isDragGlobal
		};
		case "reset": return { ...initialState };
